import {parse,names,mod,approach} from './music.js?v=2.0.0-alpha.9';
export function parseBar(text,barBeats=4){const tokens=text.trim().split(/\s+|,(?![^()]*\))/).filter(Boolean);if(tokens.length>256)throw Error('每小節最多 256 個和弦區段。');if(!tokens.length)return [];const durations=tokens.length===3?[barBeats/2,barBeats/4,barBeats/4]:tokens.map(()=>barBeats/tokens.length);return tokens.map((token,i)=>{const [symbol,beat]=token.split(':');if(symbol!=='N.C.'&&!parse(symbol))throw Error('無法辨識 '+symbol+'；Am 是小和弦，AM 是大和弦。');const beats=beat===undefined?durations[i]:Number(beat);if(!Number.isFinite(beats)||beats<=0)throw Error('拍數必須大於零。');return {symbol,beats};}).map((c,i,a)=>{if(Math.abs(a.reduce((n,c)=>n+c.beats,0)-barBeats)>.001)throw Error('每小節的拍數合計須為 '+barBeats+'。');return c;});}
export function parseChart(text,barBeats=4){let t=text.trim().replace(/[.。]+$/,'').trim();if(t.startsWith('|'))t=t.slice(1);if(t.endsWith('|'))t=t.slice(0,-1);const parts=t.split('|');if(parts.length>128)throw Error('目前最多支援 128 小節。');return parts.map(p=>({chords:parseBar(p,barBeats),reason:'原始進行'}));}
export const chordList=bar=>bar.chords??(bar.symbol?[{symbol:bar.symbol,beats:4}]:[]);
export const serialize=bars=>'| '+bars.map(b=>chordList(b).map(c=>c.symbol+':'+c.beats).join(' ')).join(' | ')+' |';
function color(symbol){const c=parse(symbol);if(c.q===''||c.q==='M')return names[c.root]+'maj7';if(c.q==='m')return names[c.root]+'m9';if(c.q==='7')return names[c.root]+'13';return symbol;}
export function solve(source,kind='color'){return source.map((b,i)=>{const list=chordList(b);if(!list.length)return {chords:[],reason:'空白'};if(kind==='original')return structuredClone(b);if(kind==='color')return {chords:list.map(c=>({...c,symbol:color(c.symbol)})),reason:'保留根音 · 加入 7 / 9 / 13 色彩'};const next=chordList(source[(i+1)%source.length])[0];if(!next)return structuredClone(b);const target=parse(next.symbol),a=approach(next.symbol);const first=list[0].symbol;if(kind==='cadence')return {chords:[{symbol:first,beats:2},{symbol:a[0],beats:1},{symbol:a[1],beats:1}],reason:'2 + 1 + 1 拍 · ii–V → '+next.symbol};if(kind==='tritone')return {chords:[{symbol:color(first),beats:2},{symbol:a[0],beats:1},{symbol:names[mod(target.root+1)]+'7',beats:1}],reason:'ii–subV → '+next.symbol+' · 半音低音解決'};return structuredClone(b);});}
